scwin.btn_refresh_onclick = function(e) {
    dataList1.setCellData(1, "col5", "세출예산현액");
    gridView1.refresh();
};
scwin.t1 = function(info) {
    var newInfo = WebSquare.extend({}, info);
    if (info.rowIndex === 0) {
        newInfo.inputType = "checkbox";
    } else {
        newInfo.inputType = "text";
    }
    return newInfo;
};
